use imu_joint_bridge::protocol::{Server,crc32};
use serde_json::{Value,json};
fn native(seq:u32)->Value{json!({"kind":"native_clock_req","sid":"native-session","seq":seq,"nonce":format!("nonce-{seq}"),"n1_ns":100000000000u64+seq as u64*1000000})}
fn ready()->Server{let mut s=Server::default();s.native(native(0),1792300000000000,1792300000000100).unwrap();s}
fn hello()->Value{json!({"p":"J_HELLO1","sid":"watch-session","w1_ms":1792300000000u64})}
fn data(payload:&str,index:u32)->Value{json!({"p":"J_DATA1","sid":"watch-session","native_sid":"native-session","index":index,"payload":payload,"crc32":crc32(payload.as_bytes())})}
#[test]fn crc_known(){assert_eq!(crc32(b"123456789"),"cbf43926");}
#[test]fn repeated_json_keys_rejected_at_boundary(){assert!(imu_joint_bridge::protocol::parse_json(r#"{"kind":"native_clock_req","sid":"one","sid":"two"}"#).is_err());assert!(imu_joint_bridge::protocol::parse_json(r#"{"nested":{"x":1,"x":2}}"#).is_err());}
#[test]fn watch_requires_native_session(){assert!(Server::default().watch(hello(),0,0).is_err());}
#[test]fn bound_hello(){let a=ready().watch(hello(),1792300000000000,1792300000000100).unwrap();assert_eq!(a.reply["native_sid"],"native-session");assert_eq!(a.reply["duration_ms"],20000);}
#[test]fn reject_foreign_native_and_unknown_keys(){let mut s=ready();let mut n=native(1);n["sid"]=json!("other");assert!(s.native(n,0,0).is_err());let mut n=native(1);n["regions"]=json!([]);assert!(s.native(n,0,0).is_err());}
#[test]fn native_sequence_replay_bound(){let mut s=ready();let a=s.native(native(1),1792300000000200,1792300000000300).unwrap();assert_eq!(a.reply["seq"],1);assert!(s.native(native(3),0,0).is_err());assert!(s.native(native(1),0,0).is_err());}
#[test]fn data_crc_and_order_and_echo(){let mut s=ready();s.watch(hello(),1,2).unwrap();let p="[[0,1792300000001,1.25,2.5,3.75],[1,1792300000061,1.5,2.25,3.5]]";let mut bad=data(p,0);bad["crc32"]=json!("00000000");assert!(s.watch(bad,1,2).is_err());let a=s.watch(data(p,0),1,2).unwrap();assert_eq!(a.reply["saved"],true);assert_eq!(s.rows(),2);assert!(s.watch(data(p,2),1,2).is_err());let a=s.watch(data(p,0),1,2).unwrap();assert_eq!(a.reply["duplicate"],true);assert_eq!(s.rows(),2);}
#[test]fn crc_valid_payload_wrong_sequence_rejected(){let mut s=ready();s.watch(hello(),1,2).unwrap();assert!(s.watch(data("[[2,1792300000001,1,2,3]]",0),1,2).is_err());}
#[test]fn conflicting_replay_rejected(){let mut s=ready();s.watch(hello(),1,2).unwrap();s.watch(data("[[0,1792300000001,1,2,3]]",0),1,2).unwrap();assert!(s.watch(data("[[0,1792300000001,4,2,3]]",0),1,2).is_err());}
#[test]fn sealed_counts_bound(){let mut s=ready();s.watch(hello(),1,2).unwrap();s.watch(data("[[0,1792300000001,1,2,3]]",0),1,2).unwrap();let mut end=json!({"p":"J_END1","sid":"watch-session","native_sid":"native-session","count":2,"blocks":1,"start_ms":1792300000000u64,"stop_ms":1792300020000u64,"stop_reason":"duration","clock_observations":0,"acquisition":{}});assert!(s.watch(end.clone(),1,2).is_err());end["count"]=json!(1);let a=s.watch(end,1,2).unwrap();assert_eq!(a.reply["saved"],true);assert!(s.complete());}
#[test]fn millisecond_tie_at_manual_stop_is_retained(){let mut s=ready();s.watch(hello(),1,2).unwrap();s.watch(data("[[0,1792300000001,1,2,3]]",0),1,2).unwrap();let end=json!({"p":"J_END1","sid":"watch-session","native_sid":"native-session","count":1,"blocks":1,"start_ms":1792300000000u64,"stop_ms":1792300000001u64,"stop_reason":"user","clock_observations":0,"acquisition":{}});assert!(s.watch(end,1,2).is_ok());}
#[test]fn clock_observation_bound_and_native_nonce_echo(){let mut s=ready();s.watch(hello(),1,2).unwrap();let a=s.native(native(1),1792300000000200,1792300000000300).unwrap();assert_eq!(a.reply["nonce"],"nonce-1");let a=s.watch(json!({"p":"J_CLK_REQ1","sid":"watch-session","native_sid":"native-session","seq":0,"w1_ms":1792300000000u64}),1792300000001000,1792300000001100).unwrap();let mut o=json!({"p":"J_CLK_OBS1","sid":"watch-session","native_sid":"native-session","seq":0,"w1_ms":1792300000000u64,"w4_ms":1792300000010u64,"p2_us":a.reply["p2_us"],"p3_us":a.reply["p3_us"]});o["p2_us"]=json!(0);assert!(s.watch(o,1,2).is_err());}
